  expect(normalizeMessage(raw,'METADATA_ONLY').subject).toBeUndefined();
  expect(normalizeMessage(raw,'METADATA_ONLY').plaintextBody).toBeUndefined();
  expect(normalizeMessage(raw).htmlBody).toContain('<b>world</b>');
});

