  const events = (id?: string) => `/calendars/${segment(id ?? 'primary')}/events`;
  const list = async (a: Args) => {
    const zone = a.timeZone ?? ((a.startTime || a.endTime) && !/(?:Z|[+-]\d{2}:\d{2})$/i.test(a.startTime ?? a.endTime) ? await resolveZone(api, a) : 'UTC');
